contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs: account address to act for, amounts for make and take, and a flag to choose action.
    // The test will call either openMakeFor or openTakeFor and then assert a general relation between
    // the account's maintenance() before and maintenanceNext() after the operation when settleForAccount
    // semantics are applied via the public API (we use pre and position view getters to compute an expected
    // non-increasing property: maintenanceNext() >= 0 and should not be less than zero minus any charged fee).

    // Note: we cannot call internal collateral directly; we only observe maintenance and maintenanceNext.

    function run(address account, uint256 makeAmount, uint256 takeAmount, bool doMake) public payable {
        require(account != address(0));
        // Record maintenance before any action
        // maintenance and maintenanceNext are public view functions taking address
        uint256 beforeMaintenance = c.maintenance(account).truncate();
        uint256 beforeMaintenanceNext = c.maintenanceNext(account).truncate();

        // Decide which call to perform. We call as this contract (msg.sender for c will be this test contract).
        // Use safe amounts: wrap inputs into UFixed18 by calling openMakeFor/openTakeFor directly (they accept UFixed18).
        // These calls may revert; catch revert status.
        bool reverted;
        if (doMake) {
            // call openMakeFor(account, UFixed18.wrap(makeAmount))
            try c.openMakeFor(account, UFixed18.wrap(makeAmount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(takeAmount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After the attempted operation, read maintenance values again
        uint256 afterMaintenance = c.maintenance(account).truncate();
        uint256 afterMaintenanceNext = c.maintenanceNext(account).truncate();

        // General rule asserted:
        // If the call reverted then the visible maintenance values must be unchanged.
        // If it did not revert then maintenanceNext should be >= 0 (trivially true) and maintenanceNext should be at least
        // the previous maintenance minus a bounded amount (we express that it cannot increase unexpectedly when a call reverts).
        // To keep the assertion provable and meaningful: require that either the call reverted and nothing changed, or it didn't revert
        // and afterMaintenanceNext >= beforeMaintenanceNext (i.e., opening a position cannot decrease the maintenanceNext requirement).
        assert(
            (reverted && afterMaintenance == beforeMaintenance && afterMaintenanceNext == beforeMaintenanceNext)
            || (!reverted && int256(afterMaintenanceNext) >= int256(beforeMaintenanceNext))
        );
    }

    receive() external payable {}
 }

