    // Call either openMakeFor or openTakeFor exactly once (top-level). Then assert a general invariant
    // relating pre/post maintenance values and whether the call reverted.
    function run(address account, uint256 amount, bool doMake) public payable {
        require(account != address(0));

        // Read visible maintenance values before the operation
        UFixed18 beforeM = c.maintenance(account);
        UFixed18 beforeMN = c.maintenanceNext(account);

        bool reverted;

        if (doMake) {
            // top-level state-changing call, caught to detect revert
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read visible maintenance values after the operation
        UFixed18 afterM = c.maintenance(account);
        UFixed18 afterMN = c.maintenanceNext(account);

        // General rule:
        // - If the call reverted, the observable maintenance and maintenanceNext must be unchanged.
        // - If the call did not revert, maintenanceNext must not decrease (i.e. afterMN >= beforeMN).
        assert(
            (reverted && afterM.eq(beforeM) && afterMN.eq(beforeMN))
            || (!reverted && afterMN.gte(beforeMN))
        );
    }

