contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take: isMake (whether to call openMakeFor), account (target account), amount (UFixed18 wrapped uint256)
    // For simplicity we pass raw uint256 for amount which will be treated by caller as a UFixed18 value.
    function run(bool isMake, address account, uint256 amount) public payable {
        require(amount <= type(uint128).max); // keep amounts reasonable for packing
        // Precondition: product must not be closed for the test to be meaningful.
        // We observe closed() and if closed we simply assert that calling open functions would revert.

        bool preClosed = c.closed();

        // read observable state before
        uint256 beforeLatest = c.latestVersion();
        C.PrePosition memory beforePreFor = c.pre(account);
        C.PrePosition memory beforePreGlobal = c.pre();

        // Perform the call and capture revert
        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read observable state after
        uint256 afterLatest = c.latestVersion();
        C.PrePosition memory afterPreFor = c.pre(account);
        C.PrePosition memory afterPreGlobal = c.pre();

        // The general rule we assert:
        // - If product was closed then the open call must have reverted (cannot open when closed).
        // - If product was not closed, and caller invoked openMakeFor/openTakeFor as the account (msg.sender == account),
        //   then the call must not revert and the account's pre() should reflect an increase in the corresponding open amount.
        // - latestVersion() should be unchanged by these pre-positioning operations.

        // Determine whether this contract was effectively the account (msg.sender for c is this contract)
        bool callerIsAccount = (account == address(this));

        if (preClosed) {
            // If product closed before, open operations should revert (we observed revert flag)
            assert(reverted == true);
        } else {
            if (callerIsAccount) {
                // Must not revert
                assert(reverted == false);

                // latestVersion unchanged
                assert(afterLatest == beforeLatest);

                // pre() for account should have increased either openMake or openTake amount
                // We can't directly inspect types, but we can compare that either openPosition.openMake or openPosition.openTake increased.
                // Use that the sum of open positions increases by at least amount
                uint256 beforeOpenSum = UFixed18.unwrap(beforePreFor.openPosition.maker) + UFixed18.unwrap(beforePreFor.openPosition.taker);
                uint256 afterOpenSum = UFixed18.unwrap(afterPreFor.openPosition.maker) + UFixed18.unwrap(afterPreFor.openPosition.taker);
                assert(afterOpenSum >= beforeOpenSum);

                // Also global pre() should reflect same non-decrease (global pre accumulates positions too)
                uint256 beforeGlobalOpenSum = UFixed18.unwrap(beforePreGlobal.openPosition.maker) + UFixed18.unwrap(beforePreGlobal.openPosition.taker);
                uint256 afterGlobalOpenSum = UFixed18.unwrap(afterPreGlobal.openPosition.maker) + UFixed18.unwrap(afterPreGlobal.openPosition.taker);
                assert(afterGlobalOpenSum >= beforeGlobalOpenSum);
            } else {
                // If caller is not the account, openFor may revert due to onlyAccountOrMultiInvoker; we allow either behavior
                // But latestVersion must still be unchanged (pre-positioning should not advance version)
                assert(afterLatest == beforeLatest);
            }
        }
    }

    // Allow receiving Ether if needed by future interactions
    receive() external payable {}
}

