    // account: target account for the openFor call
    // amount: raw uint256 representing a UFixed18 value (scaled by caller conventions)
    function run(bool isMake, address account, uint256 amount) public payable {
        require(amount <= type(uint128).max, "amount too large");

        // Record pre-state via public getters
        bool preClosed = c.closed();
        uint256 beforeLatest = c.latestVersion();

        C.PrePosition memory beforePreFor = c.pre(account);
        C.PrePosition memory beforePreGlobal = c.pre();

        // Make the deciding call as this contract (msg.sender for c will be this contract)
        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read post-state
        uint256 afterLatest = c.latestVersion();
        C.PrePosition memory afterPreFor = c.pre(account);
        C.PrePosition memory afterPreGlobal = c.pre();

        // If product was closed beforehand, opening must revert. Otherwise, when this contract acts on its own account,
        // the call must succeed, latestVersion must not advance, and the sum of openPosition maker+taker must not decrease
        bool callerIsAccount = (account == address(this));

        // Build sums safely (use uint256 of unwraps)
        uint256 beforeOpenSum = UFixed18.unwrap(beforePreFor.openPosition.maker) + UFixed18.unwrap(beforePreFor.openPosition.taker);
        uint256 afterOpenSum = UFixed18.unwrap(afterPreFor.openPosition.maker) + UFixed18.unwrap(afterPreFor.openPosition.taker);
        uint256 beforeGlobalOpenSum = UFixed18.unwrap(beforePreGlobal.openPosition.maker) + UFixed18.unwrap(beforePreGlobal.openPosition.taker);
        uint256 afterGlobalOpenSum = UFixed18.unwrap(afterPreGlobal.openPosition.maker) + UFixed18.unwrap(afterPreGlobal.openPosition.taker);

        assert(
            // closed => must have reverted
            (preClosed && reverted)
            || (
                // not closed and caller is account => must not revert, latestVersion unchanged, and non-decreasing pre open sums
                (!preClosed && callerIsAccount && !reverted && afterLatest == beforeLatest && afterOpenSum >= beforeOpenSum && afterGlobalOpenSum >= beforeGlobalOpenSum)
            )
            || (
                // not closed and caller is not account => allow either revert or success, but latestVersion must remain unchanged
                (!preClosed && !callerIsAccount && afterLatest == beforeLatest)
            )
        );
    }

    receive() external payable {}
}

