contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // isMake: true => call openMakeFor, false => call openTakeFor
    // account: target account for the openFor call
    // amount: raw uint256 to wrap as UFixed18 via UFixed18.wrap(amount)
    function run(bool isMake, address account, uint256 amount) public payable {
        require(amount <= type(uint128).max, "amount too large");

        // Observe pre-state through public getters
        bool preClosed = c.closed();
        uint256 beforeLatest = c.latestVersion();

        // Read pre(account).openPosition.maker and .taker using the public pre(account) getter
        // but avoid referring to internal types; use ABI-encoded call to extract the two uint256 values
        (bool okBefore, bytes memory dataBefore) = address(c).staticcall(abi.encodeWithSelector(c.pre.selector, account));
        require(okBefore, "pre view failed");
        // pre returns (uint256 oracleVersion, (UFixed18 maker, UFixed18 taker) openPosition, (UFixed18 maker, UFixed18 taker) closePosition)
        // The encoded layout: uint256, uint256, uint256, uint256, uint256
        // We extract openPosition.maker at offset 32*1 and openPosition.taker at offset 32*2
        uint256 beforeOpenMaker;
        uint256 beforeOpenTaker;
        assembly {
            // skip the 32-byte length prefix of bytes
            let ptr := add(dataBefore, 32)
            // offset 1 -> openPosition.maker (second uint256)
            beforeOpenMaker := mload(add(ptr, 32))
            // offset 2 -> openPosition.taker (third uint256)
            beforeOpenTaker := mload(add(ptr, 64))
        }
        uint256 beforeOpenSum = beforeOpenMaker + beforeOpenTaker;

        // Perform the call as this contract so msg.sender == this contract for c
        bool reverted;
        if (isMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read post-state
        uint256 afterLatest = c.latestVersion();
        (bool okAfter, bytes memory dataAfter) = address(c).staticcall(abi.encodeWithSelector(c.pre.selector, account));
        require(okAfter, "pre view failed after");
        uint256 afterOpenMaker;
        uint256 afterOpenTaker;
        assembly {
            let ptr := add(dataAfter, 32)
            afterOpenMaker := mload(add(ptr, 32))
            afterOpenTaker := mload(add(ptr, 64))
        }
        uint256 afterOpenSum = afterOpenMaker + afterOpenTaker;

        bool callerIsAccount = (account == address(this));

        // Assert the general rule:
        // - If product was closed before the call, the call must have reverted.
        // - Otherwise, if the caller is the account itself, the call must not revert,
        //   latestVersion must remain unchanged, and that account's pre().openPosition sum must not decrease.
        // - For other callers on an open product we assert that latestVersion didn't change.
        assert(
            (preClosed && reverted)
            || (
                (!preClosed && callerIsAccount && !reverted && afterLatest == beforeLatest && afterOpenSum >= beforeOpenSum)
            )
            || (
                (!preClosed && !callerIsAccount && afterLatest == beforeLatest)
            )
        );
    }

    receive() external payable {}
