contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single-entry property test
    // params: account to operate for and an amount to open/close
    function run(address account, UFixed18 amount) public payable {
        require(account != address(0));
        // read prior position
        (UFixed18 makerBefore, UFixed18 takerBefore) = _readPosition(account);

        // perform openMakeFor then closeMakeFor as the same caller (msg.sender == address(this))
        // Invocations that change state must be top-level statements
        c.openMakeFor(account, amount);
        c.closeMakeFor(account, amount);

        // read after position
        (UFixed18 makerAfter, UFixed18 takerAfter) = _readPosition(account);

        // The general rule: net position (maker - taker) should be unchanged after open then close of same amount
        // We compare via unsafeDiv/other functions are internal; use public truncate to convert to uint parts
        // Use equality of maker and taker individually to be safe: makerAfter >= makerBefore implies any increase compensated by decrease, but best is exact equality
        assert(_uEqual(makerBefore, makerAfter) && _uEqual(takerBefore, takerAfter));
    }

    // helper to call public view position(account) which returns Position struct with maker/taker
    function _readPosition(address account) internal returns (UFixed18, UFixed18) {
        // call returns a struct; access via c.position(account)
        (UFixed18 maker, UFixed18 taker) = c.position(account);
        return (maker, taker);
    }

    // compare two UFixed18 for equality using truncate and raw unwrap via public view functions not available; we can compare by comparing truncation and relying on equality of stored value via arithmetic: use gte/lte
    function _uEqual(UFixed18 a, UFixed18 b) internal view returns (bool) {
        return a.eq(b);
    }

    receive() external payable {}
}

contract InvMutTest {
