        C.Position memory posBefore = c.position(account);

        // perform state-changing calls as top-level statements
        c.openMakeFor(account, amount);
        c.closeMakeFor(account, amount);

        // observe position after
        C.Position memory posAfter = c.position(account);

        // General rule: maker and taker must be equal to their previous values
