        assert(UFixed18.unwrap(makerBefore) == UFixed18.unwrap(makerAfter) && UFixed18.unwrap(takerBefore) == UFixed18.unwrap(takerAfter));
    }

    // helper to read c.position(account) via public view function: returns the tuple of UFixed18s
    function _readPosition(address account) private view returns (UFixed18, UFixed18) {
        C.Position memory p = c.position(account);
        return (p.maker, p.taker);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function
    // Takes an account and an amount (UFixed18 is a user-defined type in the compilation unit)
    function run(address account, UFixed18 amount) public payable {
        // avoid zero-address which may have special semantics elsewhere
        require(account != address(0));

        // Observe the public position before any state changes
        C.Position memory before = c.position(account);

        // Perform the state-changing sequence as top-level statements
        c.openMakeFor(account, amount);
        c.closeMakeFor(account, amount);

        // Observe the public position after the sequence
        C.Position memory after = c.position(account);

        // General rule: public maker and taker must be equal to their before-values
        // Compare the unwrap of the UFixed18 values by relying on the public getters returning the same type
        // We compare by reading their underlying uint256 via converting through a view call to truncate()
        // since UFixed18 has truncate(UFixed18) public in the library, but to stay within constraints,
        // we perform equality on the encoded values by comparing ABI-encoded lengths via simple checks:
        // Directly compare the UFixed18 values by reusing that they are returned as the same type and
        // the Solidity == for structs is not available. So compare truncated integer parts and also
        // compare their .truncate() via calling c.maintenance(address) as a stand-in is not correct.
        // Instead, compare encoding via abi.encodePacked which is allowed in assert.

        bytes memory encBefore = abi.encodePacked(before.maker, before.taker);
        bytes memory encAfter = abi.encodePacked(after.maker, after.taker);

        assert(keccak256(encBefore) == keccak256(encAfter));
    }

    receive() external payable {}
}

