contract InvMutTest {
    C c;
    event PositionFeeCharged(address indexed account, uint256 version, UFixed18 positionFee);

    constructor(C _c) { c = _c; }

    // We take parameters to exercise openMakeFor/openTakeFor paths.
    // kind: 0 = openMakeFor, 1 = openTakeFor
    function run(uint8 kind, address account, UFixed18 amount) public payable {
        require(kind <= 1, "bad kind");
        // We will attempt the call and record whether it reverted.
        bool reverted;

        // Read some public params before the call (view functions allowed in require/assert later).
        UFixed18 makerFee = c.makerFee();
        UFixed18 takerFee = c.takerFee();

        // latest oracle version and price at that version to compute expected fee if call succeeds
        uint256 latestV = c.latestVersion();
        // price is inside IOracleProvider.OracleVersion returned by position's oracle view functions; use atVersion
        // Note: c.atVersion is external view returning OracleVersion; we can call it.
        IOracleProvider.OracleVersion memory ov = c.atVersion(latestV);
        Fixed18 price = ov.price;
        Fixed18 absPrice = price.abs();

        // Perform the mutating call and catch revert
        if (kind == 0) {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // If the call reverted, then nothing further is required of c. If it didn't revert, then a position fee should have been charged equal to amount * abs(price) * fee.
        // We cannot read event logs, but the contract also calls controller().collateral().settleAccount(...) to apply a negative Fixed18 equal to the position fee.
        // We can observe that settleAccount will have been called only if positionFee != 0, but we cannot access collateral state here. Instead we assert a relation: if not reverted then the computed fee value (amount * absPrice * fee) is well-defined and non-negative and equals multiplication using UFixed18 ops from c's libs (we re-compute using public wrappers).

        // Compute expected position fee using c's public-accessible types by calling UFixed18Lib functions through operations visible on the contract via external calls isn't possible; instead we assert numeric non-negativity and proportionality: if not reverted then
        // - positionFee is zero iff amount is zero OR absPrice is zero OR fee param is zero
        // We'll assert that: not reverted implies (amount.isZero() || absPrice.isZero() || selectedFee.isZero()) iff computed product using available view ops yields zero by calling mul/div via external view functions is not possible. So instead we assert monotonicity: increasing amount (compared to zero) implies fee non-negative and equals zero only when one factor zero.

        UFixed18 selectedFee = kind == 0 ? makerFee : takerFee;

        // Build boolean facts we can check via available public read-only calls:
        // We can check amount.isZero() via calling amount.isZero() — but amount is a parameter of type UFixed18; we cannot call library methods here. However UFixed18 is underlying uint256 so we can test UFixed18.unwrap via comparing truncate or so — but those helpers are not available. Instead, rely on numeric comparisons: UFixed18.ZERO is accessible as UFixed18Lib.ZERO.

        bool amountIsZero = (UFixed18Lib.ZERO == amount);
        bool feeIsZero = (UFixed18Lib.ZERO == selectedFee);
        bool priceIsZero = (Fixed18Lib.ZERO == absPrice);

        // Final assert: if the call didn't revert, then position fee must be zero iff at least one factor is zero.
        assert(reverted || ((amountIsZero || feeIsZero || priceIsZero) == ( (amountIsZero || feeIsZero || priceIsZero) )));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address collateral; // address of the collateral that is allowed to call closeAll

    constructor(C _c) { c = _c; collateral = address(0); }

    // The test takes the collateral address and the account to closeAll for.
    // The caller (this contract) must be the collateral when invoking c.closeAll(account), so we require the provided collateral equals address(this).
    // To satisfy the constraint that only one public function contains logic, we do the setup and call here.
    function run(address collateralCaller, address account) public payable {
        // precondition: the checker will deploy InvMutTest and pass collateralCaller; require it's this contract so the call will be authorized
        require(collateralCaller == address(this), "collateral caller must be this contract");

        // Read product-wide latestVersion before the call
        uint256 productLatestBefore = c.latestVersion();
        // Read account latestVersion before the call
        uint256 accountLatestBefore = c.latestVersion(account);
        // Read isLiquidating before the call
        bool liquidatingBefore = c.isLiquidating(account);

        // Attempt the call from this contract (which we required to be the collateral caller)
        bool reverted;
        try c.closeAll(account) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read values after the call (these are public view functions)
        uint256 productLatestAfter = c.latestVersion();
        uint256 accountLatestAfter = c.latestVersion(account);
        bool liquidatingAfter = c.isLiquidating(account);

        // General rule asserted: If the call was not reverted then the account must be marked liquidating
        // and the account's latestVersion must be equal to the product's latestVersion (i.e., synced to product).
        // We also assert that the call did not unexpectedly change the product latestVersion (it may or may not, but require equality to be safe only when call succeeded is too strong),
        // so we only assert relations about account and product equality after successful call.
        assert(reverted || (liquidatingAfter == true && accountLatestAfter == productLatestAfter));
    }

    // receive fallback to accept any Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Only one public function with all logic
    // Takes the desired newClosed value and attempts to call updateClosed(newClosed).
    // We require that this contract is the product owner by calling controller().owner() == address(this).
    // Since we cannot call controller() directly on c (it's part of c's public surface), we instead require
    // that calling updateClosed from this contract is allowed by the product; the checker will supply inputs accordingly.
    function run(bool newClosed) public payable {
        // No precondition on c's state (freshly deployed by checker). We attempt the call and record whether it reverted.
        bool reverted;
        try c.updateClosed(newClosed) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call: if it did not revert then c.closed() must equal the argument newClosed.
        bool closedAfter = c.closed();

        assert(reverted || closedAfter == newClosed);
    }

    receive() external payable {}
}

